    -- Connection c2: nchar0.M_NChar to rmap0.S_Pkt
    rmap0_S_Pkt_TData_s    <= nchar0_M_NChar_Data_s;
    rmap0_S_Pkt_TLast_s    <= nchar0_M_NChar_Last_s;
    nchar0_M_NChar_Ready_s <= rmap0_S_Pkt_TReady_s;
    rmap0_S_Pkt_TValid_s   <= nchar0_M_NChar_Valid_s;

